use serde_json::{json,Value};
use kfc::{cn::wps::kfc::numfmt::{global::GlobalEnv::GlobalEnv,usermodel::NumFmtAnalyzer::NumFmtAnalyzer},native_runtime::Character};
use std::panic::{catch_unwind,AssertUnwindSafe};
fn base64(bytes:&[u8])->String{let a=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut s=String::new();for p in bytes.chunks(3){let n=((p[0]as u32)<<16)|((p.get(1).copied().unwrap_or(0)as u32)<<8)|p.get(2).copied().unwrap_or(0)as u32;for i in 0..4{s.push(if i>p.len(){'='}else{a[((n>>(18-i*6))&63)as usize]as char});}}s}
#[test]
fn original_android_format_analyzer_locale_history(){
 let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/format-analyzer-r0b41");let j:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let flags:Vec<_>=(0..=65535).map(|c|if Character::isDigit(c){1}else{0}|if Character::isLetter(c){2}else{0}|if Character::isUpperCase(c){4}else{0}|if Character::isLowerCase(c){8}else{0}).collect();GlobalEnv::setLCID(j["initialLCID"].as_i64().unwrap()as i16);let old=GlobalEnv::getDefaultLCID();let mut analyzer=NumFmtAnalyzer::new();let mut stages=vec![];
 for lcid in input["locales"].as_array().unwrap(){let lcid=lcid.as_i64().unwrap()as i16;GlobalEnv::setLCID(lcid);analyzer.resetDic(lcid);let results:Vec<_>=input["codes"].as_array().unwrap().iter().map(|code|{match catch_unwind(AssertUnwindSafe(||analyzer.analyse(code.as_str().unwrap()))){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":if s.contains("NullPointerException"){String::from("NullPointerException")}else{format!("panic: {s}")}})}}}).collect();stages.push(json!({"lcid":lcid,"defaultLCID":GlobalEnv::getDefaultLCID(),"results":results}));}GlobalEnv::setLCID(old);let actual=json!({"initialLCID":old,"characterFlags":base64(&flags),"stages":stages});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();let mut differences=vec![];assert_eq!(actual["characterFlags"],j["characterFlags"]);for(n,(a,b))in actual["stages"].as_array().unwrap().iter().zip(j["stages"].as_array().unwrap()).enumerate(){assert_eq!(a["defaultLCID"],b["defaultLCID"]);for(i,(a,b))in a["results"].as_array().unwrap().iter().zip(b["results"].as_array().unwrap()).enumerate(){if a!=b{differences.push(json!({"stage":n,"case":i,"input":input["codes"][i],"java":b,"rust":a}));}}}std::fs::write(p.join("differences.json"),serde_json::to_vec_pretty(&differences).unwrap()).unwrap();assert!(differences.is_empty(),"{} differences; first {:?}",differences.len(),differences.first());
}
